package com.cpf.notification.sms;import com.cpf.starter.notification.CpfNotificationProvider;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;import org.springframework.context.annotation.Bean;@AutoConfiguration @ConditionalOnBean(CpfSmsProvider.class) public class CpfSmsAutoConfiguration {@Bean CpfSmsDispatcher cpfSmsDispatcher(CpfSmsProvider p){return new CpfSmsDispatcher(p);}@Bean CpfNotificationProvider cpfSmsNotificationAdapter(CpfSmsDispatcher d){return new CpfSmsNotificationAdapter(d);}}
